export const CATALOG = Object.freeze(Object.fromEntries(Object.entries(RAW).map(([area, themes]) => [area, themes.map(theme => ({
  title: theme.title[0], problem: theme.problem[0], objective: theme.objective[0], measures: theme.measures.map(item => ({ text: item.it, instrument: item.instrument }))
}))])));

// the pairs of the phrase-book (Italian, English): every text above once (the same sentence is never listed twice)
const seen = new Set();
export const ALL_PAIRS = [];
const add = (it, en) => { if (!seen.has(it)) { seen.add(it); ALL_PAIRS.push([it, en]); } };
for (const themes of Object.values(RAW)) for (const theme of themes) { add(...theme.title); add(...theme.problem); add(...theme.objective); for (const item of theme.measures) add(item.it, item.en); }

// a theme of an area: the four texts that start together (a title, a problem, an objective and the measures of that theme); each can then be changed or replaced separately.
export const themesOf = area => CATALOG[area] ?? [];
// the measures an area offers: the ones of its themes and the ones of the model of the policy area (the same sentence is not offered twice)
export function measuresOf(area, ownInstruments = {}) {
  const out = [], seenText = new Set();
  for (const theme of themesOf(area)) for (const item of theme.measures) if (!seenText.has(item.text)) { seenText.add(item.text); out.push(item); }
  for (const [instrument, text] of Object.entries(ownInstruments ?? {})) if (text && !seenText.has(text)) { seenText.add(text); out.push({ text, instrument }); }
  return out;
}
